-- learning-platform/src/main/resources/sql/schema-learning-platform.sql

-- Create Database
CREATE DATABASE IF NOT EXISTS learning_platform
    DEFAULT CHARACTER SET utf8mb4
    COLLATE utf8mb4_general_ci;

USE learning_platform;

-- User table (includes your learning information fields)
DROP TABLE IF EXISTS user;
CREATE TABLE user (
                      id BIGINT PRIMARY KEY AUTO_INCREMENT,
                      username VARCHAR(50) NOT NULL UNIQUE,
                      password VARCHAR(100) NOT NULL,
                      phone VARCHAR(20) UNIQUE,
                      email VARCHAR(100) UNIQUE,
                      avatar_url VARCHAR(2000) DEFAULT '/image/avatar/default-avatar.png',
                      role VARCHAR(20) NOT NULL DEFAULT 'USER',
                      gender VARCHAR(20),
                      learning_preference VARCHAR(255),
                      course_interest VARCHAR(255),
                      learning_goal VARCHAR(50),
                      status VARCHAR(20) DEFAULT 'ACTIVE' COMMENT 'User status: ACTIVE, FROZEN',
                      create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
                      update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);


-- Course table
DROP TABLE IF EXISTS course;
CREATE TABLE course (
                        id BIGINT PRIMARY KEY AUTO_INCREMENT,
                        title VARCHAR(100) NOT NULL,
                        description TEXT,
                        detail_description TEXT COMMENT 'Course detailed description',
                        level VARCHAR(20),
                        category VARCHAR(50),
                        cover_url VARCHAR(255),
                        teacher VARCHAR(50),
                        teacher_intro TEXT COMMENT 'Teacher introduction',
                        price DECIMAL(10,2) DEFAULT 0,
                        tags VARCHAR(500) COMMENT 'Course tags, multiple tags separated by commas, including learning preferences and course interests',
                        course_outline TEXT COMMENT 'Course outline, stored in JSON format',
                        course_images TEXT COMMENT 'Course images, stored as JSON with multiple image URLs',
                        duration VARCHAR(50) COMMENT 'Course duration, e.g. 40 hours',
                        student_count INT DEFAULT 0 COMMENT 'Number of students',
                        rating DECIMAL(3,2) DEFAULT 0 COMMENT 'Course rating, 0-5 points',
                        create_time DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- User-Course association table
DROP TABLE IF EXISTS user_course;
CREATE TABLE user_course (
                             id BIGINT PRIMARY KEY AUTO_INCREMENT,
                             user_id BIGINT NOT NULL,
                             course_id BIGINT NOT NULL,
                             join_time DATETIME DEFAULT CURRENT_TIMESTAMP,
                             UNIQUE KEY uk_user_course (user_id, course_id),
                             KEY idx_user_id (user_id),
                             KEY idx_course_id (course_id)
);

-- Daily learning check-in table
DROP TABLE IF EXISTS study_check_in;
CREATE TABLE study_check_in (
                                id BIGINT PRIMARY KEY AUTO_INCREMENT,
                                user_id BIGINT NOT NULL,
                                check_in_date DATE NOT NULL,
                                study_minutes INT DEFAULT 0,
                                note VARCHAR(255),
                                create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
                                update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                UNIQUE KEY uk_user_check_in_date (user_id, check_in_date),
                                KEY idx_user_id (user_id),
                                KEY idx_check_in_date (check_in_date)
);

-- Insert sample course data (including tags and details)
INSERT INTO course (title, description, detail_description, level, category, cover_url, teacher, teacher_intro, price, tags, course_outline, course_images, duration, student_count, rating) VALUES
('Java Fundamentals', 'Learn Java programming from scratch and master object-oriented programming basics', 'This course is an introductory course for Java programming, suitable for beginners with no prior experience. Starting from the basic syntax of the Java language, it gradually explains the core concepts of object-oriented programming, including classes, objects, inheritance, polymorphism, encapsulation, etc. Through numerous practical cases and programming exercises, it helps learners build a solid Java programming foundation.\n\nCourse Features:\n1. Beginner-friendly and progressive\n2. Theory combined with practice\n3. Rich programming exercises and project practice\n4. Professional instructor team guidance\n\nAfter completing this course, you will be able to:\n- Master Java basic syntax and data types\n- Understand object-oriented programming concepts\n- Be able to write simple Java applications\n- Lay a solid foundation for further Java framework learning', 'Elementary', 'Programming Development', '/image/course/java-basic.jpg', 'Prof. Zhang', 'Prof. Zhang has 10 years of Java development experience and has served as a senior engineer and technical expert at several well-known internet companies. Specializes in Java core technology, Spring framework, microservices architecture, and more. Teaching style is clear and practical, and has trained thousands of Java development engineers.', 0, 'Programming Development,Hands-on Practice,Visual Learning,Career Advancement', '[{"title":"Chapter 1: Java Development Environment Setup","lessons":[{"title":"Java Introduction and History","duration":"30 min"},{"title":"JDK Installation and Configuration","duration":"45 min"},{"title":"First Java Program","duration":"40 min"},{"title":"IDE Tools Usage (IntelliJ IDEA)","duration":"50 min"}]},{"title":"Chapter 2: Java Basic Syntax","lessons":[{"title":"Variables and Data Types","duration":"50 min"},{"title":"Operators and Expressions","duration":"45 min"},{"title":"Control Flow Statements","duration":"60 min"},{"title":"Array Usage","duration":"50 min"}]},{"title":"Chapter 3: Object-Oriented Programming","lessons":[{"title":"Classes and Objects Concepts","duration":"50 min"},{"title":"Encapsulation and Access Control","duration":"45 min"},{"title":"Inheritance and Polymorphism","duration":"60 min"},{"title":"Interfaces and Abstract Classes","duration":"55 min"}]},{"title":"Chapter 4: Java Core API","lessons":[{"title":"String Processing","duration":"50 min"},{"title":"Collections Framework (List, Set, Map)","duration":"80 min"},{"title":"Exception Handling","duration":"50 min"},{"title":"IO Stream Operations","duration":"60 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"Student Management System Development","duration":"120 min"},{"title":"Library Management System Development","duration":"150 min"}]}]', '["/image/course/java-basic-1.jpg","/image/course/java-basic-2.jpg","/image/course/java-basic-3.jpg"]', '40 hours', 1250, 4.8),
('Practical Frontend Development', 'Learn HTML, CSS, JavaScript to build modern web applications', 'This course covers frontend development from beginner to advanced level, comprehensively covering the three core technologies of HTML, CSS, and JavaScript. The course uses project-driven teaching, helping learners master modern frontend development skills through multiple real project cases.\n\nCourse Content:\n1. HTML5 semantic tags and forms\n2. CSS3 layout, animations, and responsive design\n3. JavaScript ES6+ new features\n4. DOM manipulation and event handling\n5. Frontend engineering tools usage\n\nProject Practice:\n- Personal portfolio website\n- E-commerce product display page\n- Todo application\n- Weather query application', 'Elementary', 'Frontend Development', '/image/course/frontend.jpg', 'Prof. Li', 'Prof. Li is a senior frontend development engineer with 8 years of frontend development experience. Proficient in Vue.js, React and other mainstream frameworks, and has participated in the architecture design of multiple large frontend projects. Skilled at conveying complex frontend technology in an easy-to-understand way to learners.', 0, 'Frontend Development,Visual Learning,Hands-on Practice,Career Advancement', '[{"title":"Chapter 1: HTML Basics","lessons":[{"title":"HTML Document Structure","duration":"40 min"},{"title":"Common Tags and Attributes","duration":"60 min"},{"title":"Form Elements","duration":"50 min"},{"title":"HTML5 New Features","duration":"45 min"}]},{"title":"Chapter 2: CSS Styling","lessons":[{"title":"CSS Selectors and Priority","duration":"50 min"},{"title":"Layout Techniques (Flexbox, Grid)","duration":"80 min"},{"title":"CSS3 Animations and Transitions","duration":"60 min"},{"title":"Responsive Design","duration":"70 min"}]},{"title":"Chapter 3: JavaScript Programming","lessons":[{"title":"Variables, Data Types, and Operators","duration":"50 min"},{"title":"Functions and Scope","duration":"60 min"},{"title":"DOM Manipulation","duration":"70 min"},{"title":"Event Handling","duration":"60 min"},{"title":"ES6+ New Features","duration":"80 min"}]},{"title":"Chapter 4: Project Practice","lessons":[{"title":"Personal Portfolio Website Development","duration":"180 min"},{"title":"Todo Application Development","duration":"150 min"}]}]', '["/image/course/frontend-1.jpg","/image/course/frontend-2.jpg"]', '35 hours', 980, 4.7),
('Python Data Analysis', 'Use Python for data cleaning, processing, and visualization analysis', 'This course comprehensively introduces the core skills of using Python for data analysis. From data acquisition, cleaning, processing to visualization, it systematically explains the usage of core libraries such as pandas, numpy, and matplotlib. Through real case projects, it helps learners master the complete workflow of data analysis.\n\nCourse Features:\n1. Project-driven practice for practical application\n2. Covers the complete data analysis workflow\n3. Rich cases and exercises\n4. Systematic learning from basics to advanced\n\nAfter completing this course, you will be able to:\n- Proficiently use pandas for data processing\n- Master data cleaning and preprocessing techniques\n- Use matplotlib and seaborn for data visualization\n- Complete real data analysis projects', 'Intermediate', 'Data Science', '/image/course/python-data.jpg', 'Prof. Wang', 'Prof. Wang is a senior data scientist with 12 years of experience in data analysis and machine learning. Has served as a data analysis expert at several well-known companies, specializing in Python data analysis, data mining, and business intelligence. Teaching style is rigorous and pragmatic, focusing on combining theory with practice, and has helped thousands of learners successfully transition into the data analysis field.', 199.00, 'Data Science,Reading & Writing,Independent Learning,Hands-on Practice,Career Advancement', '[{"title":"Chapter 1: Python Data Analysis Basics","lessons":[{"title":"Python Environment Setup and Jupyter Usage","duration":"40 min"},{"title":"NumPy Array Operations","duration":"60 min"},{"title":"Pandas Data Structures","duration":"70 min"},{"title":"Data Reading and Writing","duration":"50 min"}]},{"title":"Chapter 2: Data Cleaning and Preprocessing","lessons":[{"title":"Missing Value Handling","duration":"50 min"},{"title":"Outlier Detection and Handling","duration":"45 min"},{"title":"Data Transformation and Standardization","duration":"60 min"},{"title":"Data Merging and Reshaping","duration":"55 min"}]},{"title":"Chapter 3: Data Analysis and Statistics","lessons":[{"title":"Descriptive Statistical Analysis","duration":"50 min"},{"title":"Grouping and Aggregation","duration":"60 min"},{"title":"Pivot Tables and Cross Tables","duration":"50 min"},{"title":"Time Series Analysis","duration":"70 min"}]},{"title":"Chapter 4: Data Visualization","lessons":[{"title":"Matplotlib Basic Plotting","duration":"60 min"},{"title":"Seaborn Advanced Visualization","duration":"70 min"},{"title":"Interactive Chart Creation","duration":"50 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"E-commerce Data Analysis Project","duration":"120 min"},{"title":"Sales Data Visualization Analysis","duration":"150 min"}]}]', '["/image/course/python-data-1.jpg","/image/course/python-data-2.jpg"]', '30 hours', 850, 4.6),
('Enterprise Spring Boot Development', 'Master the Spring Boot framework and build enterprise-level applications', 'This course thoroughly explains the core features of the Spring Boot framework and enterprise-level application development practices. From project setup, configuration management, data access to microservices architecture, it comprehensively covers Spring Boot development skills. Through multiple enterprise-level project practices, it helps learners quickly grow into Spring Boot development experts.\n\nCourse Content:\n1. Spring Boot core principles and auto-configuration\n2. RESTful API design and implementation\n3. Database integration and JPA usage\n4. Security authentication and authorization\n5. Microservices architecture practice\n\nProject Practice:\n- Enterprise backend management system\n- E-commerce platform API development\n- Microservices architecture project', 'Intermediate', 'Backend Development', '/image/course/spring-boot.jpg', 'Prof. Zhao', 'Prof. Zhao is a Spring technology expert with 15 years of Java enterprise development experience. Has led the architecture design of multiple large Spring Boot projects and is proficient in the Spring ecosystem, microservices architecture, and distributed systems. Teaching style is clear and practical, focusing on hands-on experience, and has trained numerous Spring Boot development engineers.', 299.00, 'Programming Development,Hands-on Practice,Visual Learning,Independent Learning,Career Advancement', '[{"title":"Chapter 1: Spring Boot Introduction","lessons":[{"title":"Spring Boot Introduction and Advantages","duration":"30 min"},{"title":"Project Creation and Structure","duration":"40 min"},{"title":"Auto-Configuration Principles","duration":"50 min"},{"title":"Configuration File Management","duration":"45 min"}]},{"title":"Chapter 2: Web Development","lessons":[{"title":"RESTful API Design","duration":"60 min"},{"title":"Request Processing and Response","duration":"50 min"},{"title":"Exception Handling","duration":"45 min"},{"title":"File Upload and Download","duration":"40 min"}]},{"title":"Chapter 3: Data Access","lessons":[{"title":"JPA and Hibernate","duration":"70 min"},{"title":"MyBatis Integration","duration":"60 min"},{"title":"Transaction Management","duration":"50 min"},{"title":"Multi-DataSource Configuration","duration":"55 min"}]},{"title":"Chapter 4: Security and Authentication","lessons":[{"title":"Spring Security Basics","duration":"60 min"},{"title":"JWT Token Authentication","duration":"70 min"},{"title":"OAuth2 Integration","duration":"80 min"}]},{"title":"Chapter 5: Microservices Practice","lessons":[{"title":"Microservices Architecture Design","duration":"90 min"},{"title":"Service Registration and Discovery","duration":"70 min"},{"title":"Configuration Center Usage","duration":"60 min"},{"title":"Distributed Transaction Handling","duration":"80 min"}]}]', '["/image/course/spring-boot-1.jpg","/image/course/spring-boot-2.jpg","/image/course/spring-boot-3.jpg"]', '50 hours', 1200, 4.7),
('Vue.js Full-Stack Development', 'From frontend to backend, build full-stack applications with Vue.js', 'This course systematically explains Vue.js full-stack development technology stack, from frontend Vue framework to backend Node.js, fully mastering full-stack application development. The course covers Vue 3 new features, Vue Router, Vuex state management, Node.js backend development, and other core technologies. Through real project practice, it helps learners acquire the ability to independently develop full-stack applications.\n\nCourse Features:\n1. Comprehensive coverage of Vue 3 latest features\n2. Frontend-backend separation architecture practice\n3. Complete project development workflow\n4. Enterprise-level code standards and best practices\n\nProject Practice:\n- Task Management System (Todo App)\n- Blog platform full-stack development\n- E-commerce shopping cart system', 'Intermediate', 'Frontend Development', '/image/course/vue-fullstack.jpg', 'Prof. Chen', 'Prof. Chen is a full-stack development expert with 10 years of frontend and backend development experience. Proficient in Vue.js, React, Node.js and other technology stacks, and has participated in the development and architecture design of multiple large full-stack projects. Skilled at conveying complex technology in a clear and understandable way, and has helped many learners successfully transition to full-stack development.', 399.00, 'Frontend Development,Visual Learning,Hands-on Practice,Independent Learning,Skill Expansion', '[{"title":"Chapter 1: Vue 3 Basics","lessons":[{"title":"Vue 3 New Features Introduction","duration":"40 min"},{"title":"Composition API Usage","duration":"70 min"},{"title":"Reactive System Principles","duration":"60 min"},{"title":"Component Development Basics","duration":"50 min"}]},{"title":"Chapter 2: Vue Ecosystem Tools","lessons":[{"title":"Vue Router Routing Management","duration":"60 min"},{"title":"Pinia State Management","duration":"70 min"},{"title":"Vue CLI and Vite","duration":"50 min"},{"title":"Component Library Usage","duration":"45 min"}]},{"title":"Chapter 3: Node.js Backend Development","lessons":[{"title":"Express Framework Basics","duration":"60 min"},{"title":"RESTful API Design","duration":"70 min"},{"title":"Database Integration (MongoDB/MySQL)","duration":"80 min"},{"title":"Authentication and Authorization","duration":"70 min"}]},{"title":"Chapter 4: Frontend-Backend Integration","lessons":[{"title":"Axios Request Encapsulation","duration":"50 min"},{"title":"CORS Issue Resolution","duration":"40 min"},{"title":"Error Handling","duration":"45 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"Task Management System Development","duration":"180 min"},{"title":"Blog Platform Full-Stack Development","duration":"240 min"}]}]', '["/image/course/vue-fullstack-1.jpg","/image/course/vue-fullstack-2.jpg"]', '45 hours', 1100, 4.8),
('Practical Machine Learning', 'Learn machine learning algorithms and implement practical cases with Python', 'This course thoroughly explains the core algorithm principles and Python implementation of machine learning. From supervised learning, unsupervised learning to reinforcement learning, it systematically covers the complete machine learning workflow. Through multiple real project cases, it helps learners acquire the ability to independently solve practical machine learning problems.\n\nCourse Content:\n1. Machine learning fundamentals and mathematical principles\n2. Supervised learning algorithms (regression, classification)\n3. Unsupervised learning (clustering, dimensionality reduction)\n4. Model evaluation and optimization\n5. Deep learning introduction\n\nProject Practice:\n- House price prediction system\n- Image classification project\n- Recommendation system development', 'Advanced', 'Artificial Intelligence', '/image/course/machine-learning.jpg', 'Prof. Liu', 'Prof. Liu is a machine learning expert with a doctoral degree and 10 years of machine learning research experience. Has served as an algorithm expert at several AI companies, proficient in various machine learning algorithms and deep learning technologies. Teaching style is rigorous, focusing on combining theory with practice, and has trained numerous machine learning engineers.', 499.00, 'Artificial Intelligence,Reading & Writing,Independent Learning,Hands-on Practice,Academic Advancement', '[{"title":"Chapter 1: Machine Learning Basics","lessons":[{"title":"Machine Learning Overview","duration":"40 min"},{"title":"Python Scientific Computing Libraries","duration":"60 min"},{"title":"Data Preprocessing Techniques","duration":"70 min"},{"title":"Feature Engineering","duration":"80 min"}]},{"title":"Chapter 2: Supervised Learning","lessons":[{"title":"Linear Regression and Logistic Regression","duration":"90 min"},{"title":"Decision Trees and Random Forests","duration":"100 min"},{"title":"Support Vector Machines","duration":"80 min"},{"title":"Neural Network Basics","duration":"100 min"}]},{"title":"Chapter 3: Unsupervised Learning","lessons":[{"title":"K-means Clustering","duration":"70 min"},{"title":"Hierarchical Clustering","duration":"60 min"},{"title":"PCA Dimensionality Reduction","duration":"80 min"},{"title":"Anomaly Detection","duration":"70 min"}]},{"title":"Chapter 4: Model Optimization","lessons":[{"title":"Cross Validation","duration":"60 min"},{"title":"Hyperparameter Tuning","duration":"80 min"},{"title":"Model Ensemble Methods","duration":"90 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"House Price Prediction System","duration":"180 min"},{"title":"Image Classification Project","duration":"200 min"}]}]', '["/image/course/machine-learning-1.jpg","/image/course/machine-learning-2.jpg","/image/course/machine-learning-3.jpg"]', '60 hours', 1500, 4.9),
('UI/UX Design Fundamentals', 'Master user interface and user experience design principles', 'This course systematically introduces the core theories and practical methods of UI/UX design. From user research, information architecture to visual design, it comprehensively covers the modern product design process. Through multiple design project practices, it helps learners build professional design thinking and skills.\n\nCourse Features:\n1. Design thinking and methodology\n2. User research and needs analysis\n3. Interaction design and prototyping\n4. Visual design standards and practice\n\nProject Practice:\n- Mobile App interface design\n- Website user experience optimization\n- Product prototype design', 'Elementary', 'Design & Creativity', '/image/course/ui-ux.jpg', 'Prof. Sun', 'Prof. Sun is a senior UI/UX designer with 12 years of product design experience. Has served as design director at several well-known internet companies, specializing in user research, interaction design, and visual design. Teaching style is lively and interesting, focusing on hands-on practice, and has helped many learners successfully transition to UI/UX design.', 159.00, 'Design & Creativity,Visual Learning,Hands-on Practice,Social Learning,Skill Expansion', '[{"title":"Chapter 1: Design Fundamentals","lessons":[{"title":"UI/UX Design Overview","duration":"40 min"},{"title":"Design Principles and Standards","duration":"60 min"},{"title":"Color Theory and Application","duration":"70 min"},{"title":"Typography Design Basics","duration":"60 min"}]},{"title":"Chapter 2: User Research","lessons":[{"title":"User Persona Construction","duration":"60 min"},{"title":"User Journey Maps","duration":"70 min"},{"title":"Needs Analysis Methods","duration":"60 min"}]},{"title":"Chapter 3: Information Architecture","lessons":[{"title":"Information Architecture Design","duration":"70 min"},{"title":"Navigation System Design","duration":"60 min"},{"title":"Content Organization Strategy","duration":"50 min"}]},{"title":"Chapter 4: Interaction Design","lessons":[{"title":"Interaction Design Principles","duration":"70 min"},{"title":"Prototyping Tools Usage","duration":"80 min"},{"title":"Usability Testing","duration":"60 min"}]},{"title":"Chapter 5: Visual Design","lessons":[{"title":"Interface Visual Design","duration":"90 min"},{"title":"Design System Construction","duration":"100 min"},{"title":"Mobile Design Standards","duration":"80 min"}]}]', '["/image/course/ui-ux-1.jpg","/image/course/ui-ux-2.jpg"]', '35 hours', 920, 4.6),
('Practical Product Management', 'Learn product planning, requirements analysis, and project management', 'This course systematically explains the core work methods and skills of product managers. From market analysis, needs discovery to product planning, project management, it comprehensively covers the complete product manager workflow. Through real cases and project practice, it helps learners quickly grow into excellent product managers.\n\nCourse Content:\n1. Product thinking and methodology\n2. Market analysis and competitive research\n3. Needs discovery and user research\n4. Product planning and Roadmap\n5. Project management and team collaboration\n\nProject Practice:\n- Product Requirements Document (PRD) writing\n- Product Roadmap planning\n- Project management practice', 'Intermediate', 'Business Management', '/image/course/product-manager.jpg', 'Prof. Zhou', 'Prof. Zhou is a senior product manager with 15 years of product management experience. Has served as product director at several well-known internet companies, leading multiple successful products from 0 to 1. Specializes in product strategic planning, needs analysis, and team management, and has trained numerous excellent product managers.', 259.00, 'Business Management,Social Learning,Reading & Writing,Visual Learning,Career Advancement', '[{"title":"Chapter 1: Product Thinking","lessons":[{"title":"Product Manager Role Definition","duration":"40 min"},{"title":"Product Thinking Development","duration":"60 min"},{"title":"Business Model Analysis","duration":"70 min"}]},{"title":"Chapter 2: Market Analysis","lessons":[{"title":"Market Research Methods","duration":"60 min"},{"title":"Competitive Analysis Techniques","duration":"70 min"},{"title":"User Persona Construction","duration":"60 min"}]},{"title":"Chapter 3: Requirements Management","lessons":[{"title":"Needs Discovery Methods","duration":"70 min"},{"title":"Requirements Prioritization","duration":"60 min"},{"title":"Requirements Document Writing","duration":"80 min"}]},{"title":"Chapter 4: Product Planning","lessons":[{"title":"Product Roadmap Planning","duration":"90 min"},{"title":"Feature Design Methods","duration":"80 min"},{"title":"MVP Design Strategy","duration":"70 min"}]},{"title":"Chapter 5: Project Management","lessons":[{"title":"Agile Development Methods","duration":"80 min"},{"title":"Team Collaboration Techniques","duration":"70 min"},{"title":"Data Analysis and Iteration","duration":"90 min"}]}]', '["/image/course/product-manager-1.jpg","/image/course/product-manager-2.jpg"]', '40 hours', 1050, 4.7),
('React Frontend Framework', 'In-depth learning of the React framework to build high-performance single-page applications', 'This course thoroughly explains the core concepts and advanced features of the React framework. From component development, state management to performance optimization, it comprehensively covers React development skills. Through multiple real project practices, it helps learners build enterprise-level React applications.\n\nCourse Features:\n1. In-depth React Hooks explanation\n2. State management best practices\n3. Performance optimization techniques\n4. Enterprise-level project architecture\n\nProject Practice:\n- Todo application\n- E-commerce shopping cart system\n- Social network application', 'Intermediate', 'Frontend Development', '/image/course/react.jpg', 'Prof. Wu', 'Prof. Wu is a React technology expert with 10 years of frontend development experience. Proficient in React, Redux, Next.js and other technology stacks, and has participated in the development of multiple large React projects. Teaching style is clear and easy to understand, focusing on hands-on practice, and has helped numerous learners master React development skills.', 299.00, 'Frontend Development,Visual Learning,Hands-on Practice,Independent Learning,Skill Expansion', '[{"title":"Chapter 1: React Basics","lessons":[{"title":"React Introduction and Core Concepts","duration":"50 min"},{"title":"JSX Syntax Details","duration":"60 min"},{"title":"Component Development Basics","duration":"70 min"},{"title":"Props and State","duration":"60 min"}]},{"title":"Chapter 2: React Hooks","lessons":[{"title":"useState and useEffect","duration":"80 min"},{"title":"Custom Hooks","duration":"70 min"},{"title":"useContext and useReducer","duration":"80 min"},{"title":"Performance Optimization Hooks","duration":"70 min"}]},{"title":"Chapter 3: State Management","lessons":[{"title":"Redux Basics","duration":"90 min"},{"title":"Redux Toolkit Usage","duration":"80 min"},{"title":"State Management Best Practices","duration":"70 min"}]},{"title":"Chapter 4: Routing and Data Fetching","lessons":[{"title":"React Router Usage","duration":"70 min"},{"title":"Data Fetching and Caching","duration":"80 min"},{"title":"Error Handling","duration":"60 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"Todo Application Development","duration":"180 min"},{"title":"E-commerce Shopping Cart System","duration":"240 min"}]}]', '["/image/course/react-1.jpg","/image/course/react-2.jpg"]', '45 hours', 1300, 4.8),
('Node.js Backend Development', 'Build server-side applications and APIs with Node.js', 'This course systematically explains Node.js backend development technology. From basic syntax, asynchronous programming to framework usage, database integration, it comprehensively covers Node.js server-side development skills. Through multiple real project practices, it helps learners build high-performance Node.js applications.\n\nCourse Content:\n1. Node.js core modules and API\n2. Express framework development\n3. Asynchronous programming and event loop\n4. Database integration (MongoDB/MySQL)\n5. RESTful API design and implementation\n\nProject Practice:\n- Blog system backend development\n- Real-time chat application\n- E-commerce API service', 'Intermediate', 'Backend Development', '/image/course/nodejs.jpg', 'Prof. Zheng', 'Prof. Zheng is a Node.js technology expert with 12 years of backend development experience. Proficient in Node.js, Express, MongoDB and other technology stacks, and has led the architecture design of multiple large Node.js projects. Teaching style is clear and practical, focusing on hands-on experience, and has trained numerous Node.js development engineers.', 349.00, 'Programming Development,Hands-on Practice,Visual Learning,Independent Learning,Career Advancement', '[{"title":"Chapter 1: Node.js Basics","lessons":[{"title":"Node.js Environment Setup","duration":"40 min"},{"title":"Core Module Usage","duration":"70 min"},{"title":"Asynchronous Programming Basics","duration":"80 min"},{"title":"Event Loop Mechanism","duration":"70 min"}]},{"title":"Chapter 2: Express Framework","lessons":[{"title":"Express Basic Usage","duration":"60 min"},{"title":"Routing and Middleware","duration":"80 min"},{"title":"Request Processing and Response","duration":"70 min"},{"title":"Error Handling","duration":"60 min"}]},{"title":"Chapter 3: Database Integration","lessons":[{"title":"MongoDB Operations","duration":"90 min"},{"title":"Mongoose Usage","duration":"80 min"},{"title":"MySQL Integration","duration":"70 min"},{"title":"Database Design Best Practices","duration":"60 min"}]},{"title":"Chapter 4: API Development","lessons":[{"title":"RESTful API Design","duration":"80 min"},{"title":"Authentication and Authorization","duration":"90 min"},{"title":"API Documentation Writing","duration":"60 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"Blog System Backend Development","duration":"200 min"},{"title":"Real-time Chat Application","duration":"240 min"}]}]', '["/image/course/nodejs-1.jpg","/image/course/nodejs-2.jpg"]', '50 hours', 1150, 4.7),
('MySQL Database Design', 'Learn database design principles and SQL optimization techniques', 'This course systematically explains MySQL database design principles and SQL optimization techniques. From database design standards, SQL statement writing to performance optimization, index design, it comprehensively covers MySQL database development skills. Through multiple practice projects, it helps learners become excellent database development engineers.\n\nCourse Content:\n1. Database design principles and normalization\n2. SQL statement writing and optimization\n3. Index design and optimization\n4. Transactions and locking mechanisms\n5. Performance tuning techniques\n\nProject Practice:\n- E-commerce database design\n- Data analysis query optimization\n- High-concurrency scenario optimization', 'Elementary', 'Data Science', '/image/course/mysql.jpg', 'Prof. Qian', 'Prof. Qian is a database technology expert with 13 years of database development and management experience. Proficient in MySQL, PostgreSQL and other database systems, and has led the design and optimization of multiple large database projects. Teaching style is rigorous, focusing on hands-on practice, and has trained numerous database development engineers.', 199.00, 'Data Science,Reading & Writing,Independent Learning,Visual Learning,Career Advancement', '[{"title":"Chapter 1: Database Basics","lessons":[{"title":"MySQL Installation and Configuration","duration":"40 min"},{"title":"Database Design Principles","duration":"70 min"},{"title":"Data Types and Constraints","duration":"60 min"}]},{"title":"Chapter 2: SQL Statements","lessons":[{"title":"DDL Data Definition Language","duration":"60 min"},{"title":"DML Data Manipulation Language","duration":"80 min"},{"title":"DQL Data Query Language","duration":"100 min"},{"title":"Subqueries and Joins","duration":"90 min"}]},{"title":"Chapter 3: Indexing and Optimization","lessons":[{"title":"Index Principles and Design","duration":"80 min"},{"title":"SQL Performance Optimization","duration":"90 min"},{"title":"Execution Plan Analysis","duration":"70 min"}]},{"title":"Chapter 4: Advanced Features","lessons":[{"title":"Transactions and ACID","duration":"70 min"},{"title":"Locking Mechanisms","duration":"80 min"},{"title":"Stored Procedures and Functions","duration":"90 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"E-commerce Database Design","duration":"180 min"},{"title":"Query Optimization Practice","duration":"150 min"}]}]', '["/image/course/mysql-1.jpg","/image/course/mysql-2.jpg"]', '35 hours', 980, 4.6),
('Deep Learning Fundamentals', 'Learn deep learning theory and practice from scratch', 'This course systematically explains the core theories and practical methods of deep learning. From neural network fundamentals, CNN, RNN to Transformer architecture, it comprehensively covers deep learning technology. Through multiple practice projects, it helps learners acquire the ability to independently develop deep learning applications.\n\nCourse Features:\n1. Solid theoretical foundation, progressive learning\n2. Rich practice projects for practical application\n3. Covers mainstream deep learning frameworks\n4. Systematic learning from beginner to advanced\n\nProject Practice:\n- Image classification project\n- Text sentiment analysis\n- Generative adversarial network application', 'Advanced', 'Artificial Intelligence', '/image/course/deep-learning.jpg', 'Prof. Zhou', 'Prof. Zhou is a deep learning expert with a doctoral degree and 12 years of deep learning research experience. Has served as an algorithm expert at several AI companies, proficient in TensorFlow, PyTorch and other frameworks. Teaching style is clear and practical, focusing on combining theory with practice, and has trained numerous deep learning engineers.', 599.00, 'Artificial Intelligence,Reading & Writing,Independent Learning,Visual Learning,Academic Advancement', '[{"title":"Chapter 1: Neural Network Basics","lessons":[{"title":"Perceptron and Multi-Layer Perceptron","duration":"70 min"},{"title":"Backpropagation Algorithm","duration":"90 min"},{"title":"Activation Functions","duration":"60 min"},{"title":"Loss Functions and Optimizers","duration":"80 min"}]},{"title":"Chapter 2: Convolutional Neural Networks","lessons":[{"title":"CNN Principles and Structure","duration":"90 min"},{"title":"Classic CNN Architectures","duration":"100 min"},{"title":"Image Classification Practice","duration":"120 min"}]},{"title":"Chapter 3: Recurrent Neural Networks","lessons":[{"title":"RNN and LSTM","duration":"100 min"},{"title":"GRU Networks","duration":"80 min"},{"title":"Sequence Modeling Applications","duration":"90 min"}]},{"title":"Chapter 4: Transformer Architecture","lessons":[{"title":"Attention Mechanism","duration":"90 min"},{"title":"Transformer Principles","duration":"100 min"},{"title":"BERT and GPT Models","duration":"110 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"Image Classification Project","duration":"240 min"},{"title":"Text Sentiment Analysis","duration":"200 min"}]}]', '["/image/course/deep-learning-1.jpg","/image/course/deep-learning-2.jpg","/image/course/deep-learning-3.jpg"]', '70 hours', 1800, 4.9),
('Photoshop Design Skills', 'Master Photoshop image processing and design techniques', 'This course systematically explains Photoshop image processing and design techniques. From basic operations, layer management to advanced compositing, effects creation, it comprehensively covers Photoshop design skills. Through multiple design project practices, it helps learners become professional designers.\n\nCourse Content:\n1. Photoshop basic operations\n2. Layer and mask techniques\n3. Color adjustment and color management\n4. Image compositing techniques\n5. Effects creation methods\n\nProject Practice:\n- Poster design and creation\n- Product retouching\n- Creative compositing works', 'Elementary', 'Design & Creativity', '/image/course/photoshop.jpg', 'Prof. Sun', 'Prof. Sun is a senior graphic designer with 15 years of design experience. Proficient in Photoshop, Illustrator and other design software, and has provided design services for many well-known brands. Teaching style is lively and interesting, focusing on hands-on practice, and has helped numerous learners master professional design skills.', 199.00, 'Design & Creativity,Visual Learning,Hands-on Practice,Hobby & Interest', '[{"title":"Chapter 1: Photoshop Basics","lessons":[{"title":"Interface and Tool Usage","duration":"50 min"},{"title":"Layer and Selection Operations","duration":"70 min"},{"title":"Color Modes and Adjustments","duration":"60 min"}]},{"title":"Chapter 2: Image Processing","lessons":[{"title":"Image Repair Techniques","duration":"80 min"},{"title":"Color Adjustment Techniques","duration":"90 min"},{"title":"Filter Usage","duration":"70 min"}]},{"title":"Chapter 3: Layer Techniques","lessons":[{"title":"Layer Styles Application","duration":"80 min"},{"title":"Mask Techniques","duration":"90 min"},{"title":"Blend Mode Usage","duration":"70 min"}]},{"title":"Chapter 4: Image Compositing","lessons":[{"title":"Cutout Techniques","duration":"100 min"},{"title":"Image Compositing Methods","duration":"120 min"},{"title":"Effects Creation","duration":"100 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"Poster Design and Creation","duration":"180 min"},{"title":"Product Retouching","duration":"150 min"}]}]', '["/image/course/photoshop-1.jpg","/image/course/photoshop-2.jpg"]', '30 hours', 1100, 4.7),
('Practical Project Management', 'Learn core project management methods and tools', 'This course systematically explains the core methods and tools of project management. From project initiation, planning to execution and monitoring, it comprehensively covers the complete project management process. Through real project cases, it helps learners improve their project management capabilities.\n\nCourse Content:\n1. Project management fundamentals\n2. Project planning and WBS decomposition\n3. Schedule management and resource allocation\n4. Risk management and quality control\n5. Team collaboration and communication skills\n\nProject Practice:\n- Project plan development\n- Schedule tracking management\n- Team collaboration practice', 'Intermediate', 'Business Management', '/image/course/project-management.jpg', 'Prof. Li', 'Prof. Li is a senior project management expert with PMP certification and 18 years of project management experience. Has served as project manager and project director at multiple large enterprises, leading multiple successful projects. Teaching style is pragmatic, focusing on hands-on practice, and has trained numerous excellent project managers.', 299.00, 'Business Management,Social Learning,Reading & Writing,Hands-on Practice,Career Advancement', '[{"title":"Chapter 1: Project Management Basics","lessons":[{"title":"Project Management Overview","duration":"40 min"},{"title":"Project Life Cycle","duration":"50 min"},{"title":"Project Management Knowledge System","duration":"60 min"}]},{"title":"Chapter 2: Project Planning","lessons":[{"title":"Project Scope Management","duration":"70 min"},{"title":"WBS Work Decomposition","duration":"80 min"},{"title":"Project Time Management","duration":"90 min"},{"title":"Resource Planning","duration":"70 min"}]},{"title":"Chapter 3: Project Execution","lessons":[{"title":"Team Building and Management","duration":"80 min"},{"title":"Communication Management","duration":"70 min"},{"title":"Quality Management","duration":"60 min"}]},{"title":"Chapter 4: Project Monitoring","lessons":[{"title":"Schedule Tracking Methods","duration":"70 min"},{"title":"Cost Control","duration":"80 min"},{"title":"Risk Management","duration":"90 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"Project Plan Development","duration":"180 min"},{"title":"Project Execution and Monitoring","duration":"200 min"}]}]', '["/image/course/project-management-1.jpg","/image/course/project-management-2.jpg"]', '40 hours', 1080, 4.7),
('Excel Data Analysis', 'Use Excel for data analysis and visualization', 'This course systematically explains techniques for using Excel for data analysis and visualization. From basic functions, pivot tables to advanced charts, VBA programming, it comprehensively covers Excel data analysis skills. Through multiple practice cases, it helps learners improve their data analysis capabilities.\n\nCourse Content:\n1. Excel basic functions and formulas\n2. Pivot tables and pivot charts\n3. Advanced chart creation\n4. Data analysis tool usage\n5. VBA basic programming\n\nPractice Cases:\n- Sales data analysis\n- Financial report creation\n- Data visualization dashboard', 'Elementary', 'Professional Skills', '/image/course/excel.jpg', 'Prof. Wang', 'Prof. Wang is an Excel data analysis expert with 10 years of data analysis experience. Proficient in Excel advanced features, data analysis, and visualization, and has provided data analysis training for multiple enterprises. Teaching style is clear and easy to understand, focusing on hands-on practice, and has helped numerous learners improve their Excel skills.', 99.00, 'Professional Skills,Hands-on Practice,Visual Learning,Independent Learning,Career Advancement', '[{"title":"Chapter 1: Excel Basics","lessons":[{"title":"Excel Interface and Operations","duration":"40 min"},{"title":"Common Function Usage","duration":"80 min"},{"title":"Formula Writing Techniques","duration":"70 min"}]},{"title":"Chapter 2: Data Processing","lessons":[{"title":"Data Sorting and Filtering","duration":"60 min"},{"title":"Data Validation","duration":"50 min"},{"title":"Conditional Formatting","duration":"60 min"}]},{"title":"Chapter 3: Data Analysis","lessons":[{"title":"Pivot Tables","duration":"90 min"},{"title":"Data Analysis Tools","duration":"80 min"},{"title":"Advanced Function Applications","duration":"100 min"}]},{"title":"Chapter 4: Data Visualization","lessons":[{"title":"Chart Creation Techniques","duration":"90 min"},{"title":"Dynamic