ltithreading Basics","duration":"110 min"},{"title":"Thread Synchronization","duration":"120 min"},{"title":"Asynchronous Programming","duration":"110 min"}]},{"title":"Chapter 5: Project Practice","lessons":[{"title":"High-Performance Computing Program","duration":"300 min"},{"title":"Concurrent Server Development","duration":"360 min"}]}]', '["/image/course/cpp-1.jpg","/image/course/cpp-2.jpg"]', '60 hours', 1450, 4.8),
