-- ============================================
-- Learning Community Related Tables
-- ============================================

-- Post table
DROP TABLE IF EXISTS post;
CREATE TABLE post (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    user_id BIGINT NOT NULL COMMENT 'Publisher ID',
    title VARCHAR(200) NOT NULL COMMENT 'Post title',
    content TEXT NOT NULL COMMENT 'Post content',
    type VARCHAR(20) NOT NULL DEFAULT 'discussion' COMMENT 'Post type: discussion, question, experience',
    category VARCHAR(50) COMMENT 'Category: Programming Development, Frontend Development, Backend Development, Data Science, Design & Creativity, Business Management, Professional Skills, Artificial Intelligence',
    course_id BIGINT COMMENT 'Related course ID (optional)',
    tags VARCHAR(500) COMMENT 'Tags, multiple separated by commas',
    attachment_url VARCHAR(500) COMMENT 'Attachment download URL (optional)',
    view_count INT DEFAULT 0 COMMENT 'View count',
    like_count INT DEFAULT 0 COMMENT 'Like count',
    comment_count INT DEFAULT 0 COMMENT 'Comment count',
    favorite_count INT DEFAULT 0 COMMENT 'Favorite count',
    status VARCHAR(20) DEFAULT 'published' COMMENT 'Status: published, deleted',
    visibility VARCHAR(20) DEFAULT 'PUBLIC' COMMENT 'Visibility: PUBLIC, PRIVATE',
    is_top TINYINT(1) DEFAULT 0 COMMENT 'Is pinned',
    is_resolved TINYINT(1) DEFAULT 0 COMMENT 'Is resolved (question type only)',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_user_id (user_id),
    KEY idx_category (category),
    KEY idx_course_id (course_id),
    KEY idx_type (type),
    KEY idx_create_time (create_time)
) COMMENT 'Post table';

-- Comment table
DROP TABLE IF EXISTS comment;
CREATE TABLE comment (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    post_id BIGINT NOT NULL COMMENT 'Post ID',
    user_id BIGINT NOT NULL COMMENT 'Commenter ID',
    parent_id BIGINT DEFAULT NULL COMMENT 'Parent comment ID (for replies)',
    content TEXT NOT NULL COMMENT 'Comment content',
    like_count INT DEFAULT 0 COMMENT 'Like count',
    is_best_answer TINYINT(1) DEFAULT 0 COMMENT 'Is best answer (question type only)',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY idx_post_id (post_id),
    KEY idx_user_id (user_id),
    KEY idx_parent_id (parent_id)
) COMMENT 'Comment table';

-- Like table
DROP TABLE IF EXISTS post_like;
CREATE TABLE post_like (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    post_id BIGINT NOT NULL COMMENT 'Post ID',
    user_id BIGINT NOT NULL COMMENT 'User ID',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_post_user (post_id, user_id),
    KEY idx_post_id (post_id),
    KEY idx_user_id (user_id)
) COMMENT 'Post like table';

-- Comment like table
DROP TABLE IF EXISTS comment_like;
CREATE TABLE comment_like (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    comment_id BIGINT NOT NULL COMMENT 'Comment ID',
    user_id BIGINT NOT NULL COMMENT 'User ID',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_comment_user (comment_id, user_id),
    KEY idx_comment_id (comment_id),
    KEY idx_user_id (user_id)
) COMMENT 'Comment like table';

-- Favorite table
DROP TABLE IF EXISTS favorite;
CREATE TABLE favorite (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    post_id BIGINT NOT NULL COMMENT 'Post ID',
    user_id BIGINT NOT NULL COMMENT 'User ID',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_post_user (post_id, user_id),
    KEY idx_post_id (post_id),
    KEY idx_user_id (user_id)
) COMMENT 'Favorite table';

-- Follow table
DROP TABLE IF EXISTS follow;
CREATE TABLE follow (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    follower_id BIGINT NOT NULL COMMENT 'Follower ID',
    following_id BIGINT NOT NULL COMMENT 'Following ID',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_follower_following (follower_id, following_id),
    KEY idx_follower_id (follower_id),
    KEY idx_following_id (following_id)
) COMMENT 'Follow table';

-- Notification table
DROP TABLE IF EXISTS notification;
CREATE TABLE notification (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    user_id BIGINT NOT NULL COMMENT 'Receiver ID',
    type VARCHAR(20) NOT NULL COMMENT 'Notification type: like, comment, reply, follow, best_answer',
    related_id BIGINT COMMENT 'Related ID (post ID or comment ID)',
    from_user_id BIGINT COMMENT 'Trigger user ID',
    content VARCHAR(500) COMMENT 'Notification content',
    is_read TINYINT(1) DEFAULT 0 COMMENT 'Is read',
    create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    KEY idx_user_id (user_id),
    KEY idx_is_read (is_read),
    KEY idx_create_time (create_time)
) COMMENT 'Notification table';

-- User points table (extends user table, for points system)
-- Note: MySQL does not support IF NOT EXISTS, need manual check or stored procedure
-- If column already exists, execution will throw error, can be ignored
-- status field is already defined in CREATE TABLE, no need for ALTER TABLE
ALTER TABLE user ADD COLUMN points INT DEFAULT 0 COMMENT 'Points';
ALTER TABLE user ADD COLUMN contribution INT DEFAULT 0 COMMENT 'Contribution (posts, answers, etc.)';
-- If database already exists and does not have status field, manually execute the following:
-- ALTER TABLE user ADD COLUMN status VARCHAR(20) DEFAULT 'ACTIVE' COMMENT 'User status: ACTIVE, FROZEN';

