VALUES
(1, 'Java Learning Roadmap', 'What is the learning roadmap for Java? Welcome everyone to share their experiences and pitfalls.', 'question', 'Programming Development', 1, 'Java,Learning Roadmap,Beginner', NULL, 35, 2, 8, 1, 'published', 1, 0),
(2, 'How to Systematically Learn Frontend Development?', 'I am planning to systematically learn frontend development recently. How should I arrange the order for HTML/CSS/JavaScript and frameworks?', 'discussion', 'Frontend Development', 2, 'Frontend,HTML,CSS,JavaScript', NULL, 28, 1, 5, 0, 'published', 0, 0),
(3, 'My Python Data Analysis Self-Study Experience', 'Sharing some experience and pitfalls from zero foundation to being able to create data analysis reports, hoping it helps you.', 'experience', 'Data Science', 3, 'Python,Data Analysis,Self-Study', NULL, 42, 3, 8, 2, 'published', 0, 0),
(1, 'Java Final Project Sharing', 'I have compiled a reference material for the Java final project, including project structure, core code examples and implementation ideas, hoping to help students working on their final projects. The attachment has been uploaded and can be downloaded for viewing.', 'experience', 'Programming Development', 1, 'Java,Final Project,Project Sharing', '/uploads/community/期末大作业.pdf', 15, 1, 1, 0, 'published', 0, 0);

-- Sample comments (assuming the post ids generated above are 1, 2, 3)
INSERT INTO comment (post_id, user_id, parent_id, content, like_count, is_best_answer)
VALUES
(1, 2, NULL, 'I suggest mastering Java basic syntax first, then try some simple project practice.', 1, 0),
(1, 3, NULL, 'There are many great Java roadmap videos on Bilibili, you can follow along and build a small project first.', 1, 1),
(1, 1, NULL, 'I recommend combining official documentation with "Head First Java", doing the exercises for each chapter.', 0, 0),
(1, 4, NULL, 'One more tip: after learning the basics, try building a student management system to consolidate knowledge and improve practical skills.', 1, 0),
(1, 5, NULL, 'I recommend the official Oracle Java Tutorials, although in English, they are very systematic and comprehensive.', 0, 0),
(1, 2, 2, 'Agreed! Summarizing notes after completing a small project gives the most benefit.', 0, 0),
(1, 6, 3, '"Head First Java" is indeed great, with illustrations, suitable for beginners.', 0, 0),
(2, 1, NULL, 'You can go through HTML/CSS first, then learn vanilla JS, and later dive into one framework.', 0, 0),
(2, 3, NULL, 'You can refer to MDN learning path, then spend a weekend building a login page for practice.', 0, 0),
(2, 4, NULL, 'I suggest building a static website first (personal portfolio), then learning frameworks. This helps better understand the purpose of frameworks.', 1, 0),
(2, 7, NULL, 'Framework selection advice: Vue is relatively easier to get started with, React has a richer ecosystem, choose based on personal preference.', 2, 0),
(2, 8, 1, 'Agreed, fundamentals are important, frameworks are just tools.', 0, 0),
(3, 1, NULL, 'Persisting in building small projects is important, don\'t just read without practicing.', 2, 0),
(3, 2, NULL, 'Agreed, practice more, even imitating projects is very helpful.', 0, 0),
(3, 3, NULL, 'I recommend trying Kaggle beginner competitions, the data and tutorials are very complete.', 0, 0),
(3, 4, NULL, 'pandas and numpy are the foundation of data analysis, I suggest mastering these two libraries first.', 1, 0),
(3, 5, NULL, 'You can try crawling some public data for analysis, such as weather data, stock data, etc.', 0, 0),
(3, 8, NULL, 'I recommend the book "Python for Data Analysis", the author is the creator of pandas.', 1, 0),
